targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: api.state.upgradeSessionType === 'bulk_app_update' ? 'Generate automated tests in Bulk Update' : 'Generate automated tests',
		value: {
			'Session id': api.state.upgradeSessionId,
			'Selected': api.state.generateAtfTestsToggle
		}
	};
})

